};

// Append narration to the video prompt to guide articulation without rendering text
graph["46"].inputs.text += `\nNarration content (verbatim, do not draw on screen): ${narration}`;

// --- 2) POST /prompt ---
const client_id = (globalThis.crypto?.randomUUID && crypto.randomUUID()) || String(Date.now());
const post = await this.helpers.httpRequest({
  method: 'POST',
  url: `${COMFY_BASE}/prompt`,
  body: { prompt: graph, client_id },
  json: true,
});

const prompt_id = post?.prompt_id;
if (!prompt_id) {
  throw new Error('ComfyUI: missing prompt_id in /prompt response');
}

// --- 3) Poll /history/{prompt_id} until completed ---
let history, tries = 0;
while (true) {
  await sleep(2000);
  history = await this.helpers.httpRequest({
    method: 'GET',
    url: `${COMFY_BASE}/history/${prompt_id}`,
    json: true,
  });
  const status = history?.[prompt_id]?.status;
  if (status?.completed) break;
  if (status?.status_str?.toLowerCase?.() === 'error') {
    throw new Error(`ComfyUI job error: ${status.status_str || 'unknown'}`);
  }
  if (++tries > 600) { // ~20 minutes max
    throw new Error('Timed out waiting for ComfyUI job');
  }
}

// --- 4) Extract result files (video & audio if present) ---
const outputs = history?.[prompt_id]?.outputs || {};
const files = [];
for (const nodeId of Object.keys(outputs)) {
  const nodeOut = outputs[nodeId] || {};
  for (const key of Object.keys(nodeOut)) {
    const list = Array.isArray(nodeOut[key]) ? nodeOut[key] : [];
    for (const obj of list) {
      if (!obj?.filename) continue;
      files.push({
        filename: obj.filename,
        subfolder: obj.subfolder || '',
        type: obj.type || 'output',
        ext: (obj.filename.split('.').pop() || '').toLowerCase(),
        fromNode: nodeId,
        key,
      });
    }
  }
}

// Helper to download a ComfyUI file
async function downloadComfy(file) {
  const url = `${COMFY_BASE}/view?filename=${encodeURIComponent(file.filename)}&type=${encodeURIComponent(file.type)}&subfolder=${encodeURIComponent(file.subfolder)}`;
  const data = await this.helpers.httpRequest({ method: 'GET', url, encoding: null }); // Buffer
  const mime = file.ext === 'mp4' ? 'video/mp4' : file.ext === 'mp3' ? 'audio/mpeg' : 'application/octet-stream';
  return this.helpers.prepareBinaryData(data, file.filename, mime);
}

const item = items[0];
item.json.prompt_id = prompt_id;
item.json.history = { ok: true, outputs_found: files.length };
item.binary = item.binary || {};

// Prefer MP4 from SaveVideo (node 58), and TTS MP3 from node 104 if present
const mp4 = files.find(f => f.ext === 'mp4') || files.find(f => f.type === 'video');
const mp3 = files.find(f => f.ext === 'mp3');

if (mp4) item.binary.video = await downloadComfy.call(this, mp4);
if (mp3) item.binary.audio = await downloadComfy.call(this, mp3);

return item;

/**
 * n8n Code node: ComfyUI Single Image → Video (WAN 2.2 + EdgeTTS)
 * DISCORD UPLOAD PREP — MP4-only (Comfy mux), path+voice fixed, auto-length
 * -------------------------------------------------------------------------
 * This REPLACES your current "Discord Webhook Upload Code Node" content.
 * It submits your Comfy graph, waits for completion (adaptive backoff),
 * grabs ONLY the MP4 from history, and exposes it as item.binary.video.
 *
 * Key fixes vs your last version:
 * ✓ Sanitizes LoadImage to a filename (no file:/// URIs). Put that file in ComfyUI/input
 * ✓ Uses Comfy EdgeTTS label: "[English] en-US Andrew" (not Azure shortname)
 * ✓ Auto-sizes i2v length from narration text unless you override
 * ✓ Prefers SaveVideo(58) MP4; falls back to any .mp4 found
 * ✓ Safer helper names (no collisions)
 *
 * Discord v2 node afterwards → Attachment → Upload → Binary Property = "video".
 *
 * Optional overrides via a Set node before this:
 * json.comfyBase      → "http://127.0.0.1:8188"
 * json.imageUri       → any path/URI or filename (we sanitize to basename)
 * json.voice          → label, default "[English] en-US Andrew"
 * json.voiceSpeed     → number (default 1)
 * json.pitch          → number (default 6)
 * json.fps            → number (default 30)
 * json.minSeconds     → number (default 5)
 * json.maxSeconds     → number (default 60)
 * json.targetSeconds  → number (force duration)
 * json.outWidth       → number (default 2560)
 * json.outHeight      → number (default 1440)
 * json.saveCodec      → string (default 'libx264', e.g. 'auto')
 * json.pollMs         → number (default 2000)
 * json.maxSleepMs     → number (default 15000)
 * json.waitForever    → boolean (default true)
 * json.maxWaitMs      → number (0 = unlimited)
 * json.maxPolls       → number (0 = unlimited)
 * json.strict         → boolean (throw if no MP4; default true)
 */

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

const item = items[0] || { json: {}, binary: {} };
item.json = item.json || {};
item.binary = item.binary || {};

// --- Config ---
const CFG = {
  base: (item.json.comfyBase || 'http://127.0.0.1:8188').replace(/\/$/, ''),
  imageUri: item.json.imageUri || 'DuckBotNewsAnchor7.png',
  voice: item.json.voice || '[English] en-US Andrew',
  speed: Number(item.json.voiceSpeed ?? 1),
  pitch: Number(item.json.pitch ?? 6),
  fps: Number(item.json.fps || 30),
  minSeconds: Number(item.json.minSeconds || 5),
  maxSeconds: Number(item.json.maxSeconds || 60),
  outWidth: Number(item.json.outWidth || 2560),
  outHeight: Number(item.json.outHeight || 1440),
  saveCodec: String(item.json.saveCodec || 'libx264'),
